/* v1.4.0 major release */
.bottom-inner.guest-nav-v140{display:grid!important;grid-template-columns:repeat(5,minmax(0,1fr))!important;grid-template-rows:1fr!important;grid-auto-flow:column!important;align-items:end!important;gap:0!important;width:100%!important;max-width:none!important}
.bottom-inner.admin-nav-v140{display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr))!important;grid-template-rows:1fr!important;grid-auto-flow:column!important;align-items:end!important;gap:0!important;width:100%!important;max-width:none!important}
.bottom-inner.guest-nav-v140 .nav-item,.bottom-inner.admin-nav-v140 .nav-item{min-width:0!important;width:100%!important;margin:0!important;padding:8px 1px calc(8px + env(safe-area-inset-bottom))!important;white-space:nowrap!important}
.bottom-inner.guest-nav-v140 .nav-item>span:last-child,.bottom-inner.admin-nav-v140 .nav-item>span:last-child{font-size:9px!important;line-height:1!important;max-width:100%!important;overflow:hidden!important;text-overflow:ellipsis!important}
.bottom-inner.admin-nav-v140 .nav-item>span:last-child{font-size:8px!important}
.bottom-inner.guest-nav-v140 .ico,.bottom-inner.admin-nav-v140 .ico{width:25px!important;height:25px!important}
.bottom-inner.guest-nav-v140 .queue-ico,.bottom-inner.admin-nav-v140 .queue-ico{width:52px!important;height:52px!important}
.bottom-nav{height:92px!important;overflow:visible!important}.bottom-inner{height:92px!important}
.booking-date-browser{padding-bottom:110px}.booking-date-grid{display:grid;gap:10px}.booking-date-card{display:grid;grid-template-columns:64px minmax(0,1fr) 28px;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:var(--shadow);text-decoration:none;color:inherit}.booking-datebox.large{height:70px}.booking-date-copy{display:grid;gap:4px;min-width:0}.booking-date-copy b{font-size:15px}.booking-date-copy small{font-size:11px;color:var(--muted)}.booking-date-arrow{font-size:30px;color:var(--muted);text-align:right}.selected-booking-date{display:grid;gap:12px;margin-bottom:14px}.selected-booking-date h2{margin:3px 0 0}.booked-slot-list{display:grid;gap:10px}.booked-slot-card{display:grid;grid-template-columns:92px minmax(0,1fr) auto;align-items:center;gap:12px;padding:13px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:var(--shadow)}.booked-slot-time{display:grid;gap:1px}.booked-slot-time b{font-size:14px}.booked-slot-time span{font-size:9px;color:var(--muted);text-transform:uppercase}.booked-slot-copy{display:grid;gap:3px;min-width:0}.booked-slot-copy>b{font-size:14px}.booked-slot-copy small{font-size:10px;color:var(--muted)}.booking-request-date{margin-top:14px}.center{text-align:center}
.settings-hub-v140{display:grid;gap:12px;padding-bottom:115px}.settings-panel-v140{display:grid;gap:14px}.settings-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.settings-panel-head h2{margin:2px 0 0;font-size:20px}.update-status-v140{display:grid;grid-template-columns:1fr 1fr;gap:10px}.update-status-v140>div{display:grid;gap:3px;padding:12px;border-radius:14px;background:var(--soft);border:1px solid var(--line)}.update-status-v140 span{font-size:9px;font-weight:900;color:var(--muted);letter-spacing:.08em}.update-status-v140 b{font-size:14px}.update-notes-v140{display:grid;gap:5px;font-size:12px;line-height:1.35}.compact-theme-v140{margin-top:4px}.version-details-v140 summary{cursor:pointer;font-weight:900}.version-list-v140{display:grid;grid-template-columns:auto 1fr;gap:8px 10px;margin-top:12px;font-size:11px}.version-list-v140 span{color:var(--muted)}
@media(max-width:420px){.bottom-inner.guest-nav-v140 .nav-item>span:last-child{font-size:8px!important}.bottom-inner.admin-nav-v140 .nav-item>span:last-child{font-size:7px!important}.bottom-inner.guest-nav-v140 .queue-ico,.bottom-inner.admin-nav-v140 .queue-ico{width:48px!important;height:48px!important}.booking-date-card{grid-template-columns:56px minmax(0,1fr) 22px;gap:10px;padding:10px}.booked-slot-card{grid-template-columns:82px minmax(0,1fr);gap:9px}.booked-slot-card>.pill{grid-column:2;justify-self:start}.booking-datebox.large{height:62px}}
